'use client';
import Link from 'next/link';
import { usePathname } from 'next/navigation';
import { useEffect, useRef, useState } from 'react';
import { Brand } from './brand';
import { Icon } from './icon';
const navigation = [{ href: '/', label: 'Home' }, { href: '/about', label: 'About' }, { href: '/services', label: 'Services' }, { href: '/announcements', label: 'Announcements' }, { href: '/sermons', label: 'Sermons' }, { href: '/gallery', label: 'Gallery' }, { href: '/contact', label: 'Contact' }];
export function SiteHeader(): React.JSX.Element {
  const pathname = usePathname();
  const [open, setOpen] = useState(false);
  const toggle = useRef<HTMLButtonElement>(null);
  useEffect(() => {
    const onKey = (event: KeyboardEvent): void => {
      if (event.key === 'Escape') { setOpen(false); toggle.current?.focus(); }
    };
    document.addEventListener('keydown', onKey);
    return () => document.removeEventListener('keydown', onKey);
  }, []);
  return <>
    <a className="skip-link" href="#main-content">Skip to content</a>
    <div className="welcome-bar"><div className="container"><span><span className="small-cross">✦</span> A place for faith. A people to call family.</span><Link href="/services#visit">Your first visit starts here <Icon name="arrow-up" size={13} /></Link></div></div>
    <header className="site-header"><div className="container header-inner"><Brand /><nav aria-label="Main navigation" className="desktop-nav">{navigation.map(({ href, label }) => <Link key={href} href={href} aria-current={pathname === href ? 'page' : undefined}>{label}</Link>)}</nav><div className="header-actions"><Link href={pathname === '/account' ? '/account' : '/login'} className="member-link"><Icon name="user" size={16} />{pathname === '/account' ? 'My account' : 'Member login'}</Link><Link href="/services#visit" className="btn btn--primary btn--small">Plan your visit <Icon name="arrow-up" size={15} /></Link></div><button ref={toggle} className="menu-toggle" aria-label={open ? 'Close navigation' : 'Open navigation'} aria-expanded={open} aria-controls="mobile-navigation" onClick={() => setOpen(!open)}><Icon name={open ? 'close' : 'menu'} /></button></div>
    {open && <nav id="mobile-navigation" aria-label="Mobile navigation" className="mobile-nav container">{navigation.map(({ href, label }) => <Link key={href} href={href} onClick={() => setOpen(false)} aria-current={pathname === href ? 'page' : undefined}>{label}<Icon name="arrow" size={17} /></Link>)}<Link href="/login" onClick={() => setOpen(false)}>Member login <Icon name="user" size={17} /></Link><Link href="/services#visit" className="btn btn--primary" onClick={() => setOpen(false)}>Plan your visit <Icon name="arrow-up" /></Link></nav>}</header>
  </>;
}

